{
  "cubeName": "sales_cube",
  "queryName": "1997 sales revenue by product category and media type",
  "aggregateFunction": "Sum",
  "measure": "store_sales",
  "gamma": [
    "product_dim.product_category",
    "promotion_dim.media_type"
  ],
  "sigma": [
    "date_dim.the_year='1997'"
  ]
}

{
  "cubeName": "sales_cube",
  "queryName": "Monthly sales revenue for low-fat products in 1997",
  "aggregateFunction": "Sum",
  "measure": "store_sales",
  "gamma": [
    "date_dim.year_and_month"
  ],
  "sigma": [
    "date_dim.the_year='1997'",
    "product_dim.low_fat='Y'"
  ]
}
